import{_ as p,c as i,b as s,d as e,e as r,f as n,a as l,w as m,r as o,o as c}from"./app-BC3GIMfQ.js";const h="/assets/image1-CADJXI0L.png",g="/assets/image2-CriVHxuu.png",d="/assets/image3-yA_ABCwn.png",u="/assets/image4-C69aEfBH.png",x="/assets/algo1-DLjcnocM.png",w="/assets/image5-DP9iqAZD.png",y="/assets/image6-yf3BBkjb.png",k="/assets/algo2-Piv16oKu.png",M="/assets/image7-DAgs59kJ.png",b="/assets/image8-CoJAzyc7.png",v="/assets/image9-BYeejJb4.png",_="/assets/table1-D1aqPots.png",S="/assets/image10-Ci5b-ZAf.png",C="/assets/image11-CgtZoySN.png",P="/assets/image12-CW7aMRS3.png",T="/assets/table2-D2KFhSzK.png",L="/assets/image13-C8cmgGE6.png",f="/assets/image14-BdFN-gYn.png",D="/assets/table3-R_jws9XU.png",N="/assets/table4-DjRfswoT.png",A="/assets/image15-Dew2MlQM.png",z={},R={class:"table-of-contents"};function Q(I,a){const t=o("router-link");return c(),i("div",null,[a[19]||(a[19]=s("h1",{id:"towards-efficient-and-scalable-distributed-vector-search-with-rdma",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#towards-efficient-and-scalable-distributed-vector-search-with-rdma"},[s("span",null,"Towards Efficient and Scalable Distributed Vector Search with RDMA")])],-1)),e(" more "),a[20]||(a[20]=s("div",{class:"hint-container info"},[s("p",{class:"hint-container-title"},"相关信息"),s("p",null,[s("strong",null,"论文"),n(": Towards Efficient and Scalable Distributed Vector Search with RDMA"),s("br"),s("strong",null,"代码"),n(": "),s("a",{href:"https://github.com/...",target:"_blank",rel:"noopener noreferrer"},"Open Source 未开源"),s("br"),s("strong",null,"解读"),n(": 本文提出了一种名为 CoTra 的分布式向量检索系统，利用 RDMA 技术解决了大规模向量检索中计算效率与通信效率之间的矛盾。通过基于聚类的数据分区、协同图遍历（Co-Search 和 Pull-Push 模式）以及一系列系统级优化，实现了接近线性的扩展性，在 16 台机器上达到了单机 9.8-13.4 倍的吞吐量。")])],-1)),s("nav",R,[s("ul",null,[s("li",null,[l(t,{to:"#摘要"},{default:m(()=>a[0]||(a[0]=[n("摘要")])),_:1,__:[0]})]),s("li",null,[l(t,{to:"#_1、引言"},{default:m(()=>a[1]||(a[1]=[n("1、引言")])),_:1,__:[1]})]),s("li",null,[l(t,{to:"#_2、背景"},{default:m(()=>a[2]||(a[2]=[n("2、背景")])),_:1,__:[2]}),s("ul",null,[s("li",null,[l(t,{to:"#_2-1-向量检索与近邻图索引"},{default:m(()=>a[3]||(a[3]=[n("2.1 向量检索与近邻图索引")])),_:1,__:[3]})]),s("li",null,[l(t,{to:"#_2-2-远程直接内存访问"},{default:m(()=>a[4]||(a[4]=[n("2.2 远程直接内存访问")])),_:1,__:[4]})])])]),s("li",null,[l(t,{to:"#_3、分布式协同遍历"},{default:m(()=>a[5]||(a[5]=[n("3、分布式协同遍历")])),_:1,__:[5]}),s("ul",null,[s("li",null,[l(t,{to:"#_3-1-观察与设计见解"},{default:m(()=>a[6]||(a[6]=[n("3.1 观察与设计见解")])),_:1,__:[6]})]),s("li",null,[l(t,{to:"#_3-2-协同图遍历概述"},{default:m(()=>a[7]||(a[7]=[n("3.2 协同图遍历概述")])),_:1,__:[7]})]),s("li",null,[l(t,{to:"#_3-3-执行模式详情"},{default:m(()=>a[8]||(a[8]=[n("3.3 执行模式详情")])),_:1,__:[8]})])])]),s("li",null,[l(t,{to:"#_4、优化与实现"},{default:m(()=>a[9]||(a[9]=[n("4、优化与实现")])),_:1,__:[9]}),s("ul",null,[s("li",null,[l(t,{to:"#_4-1-rdma-友好的图布局"},{default:m(()=>a[10]||(a[10]=[n("4.1 RDMA 友好的图布局")])),_:1,__:[10]})]),s("li",null,[l(t,{to:"#_4-2-高-cpu-利用率的任务调度"},{default:m(()=>a[11]||(a[11]=[n("4.2 高 CPU 利用率的任务调度")])),_:1,__:[11]})]),s("li",null,[l(t,{to:"#_4-3-实现细节"},{default:m(()=>a[12]||(a[12]=[n("4.3 实现细节")])),_:1,__:[12]})])])]),s("li",null,[l(t,{to:"#_5、评估"},{default:m(()=>a[13]||(a[13]=[n("5、评估")])),_:1,__:[13]}),s("ul",null,[s("li",null,[l(t,{to:"#_5-1-实验设置"},{default:m(()=>a[14]||(a[14]=[n("5.1 实验设置")])),_:1,__:[14]})]),s("li",null,[l(t,{to:"#_5-2-搜索性能和可扩展性"},{default:m(()=>a[15]||(a[15]=[n("5.2 搜索性能和可扩展性")])),_:1,__:[15]})]),s("li",null,[l(t,{to:"#_5-3-微观实验和消融研究"},{default:m(()=>a[16]||(a[16]=[n("5.3 微观实验和消融研究")])),_:1,__:[16]})])])]),s("li",null,[l(t,{to:"#_6、相关工作"},{default:m(()=>a[17]||(a[17]=[n("6、相关工作")])),_:1,__:[17]})]),s("li",null,[l(t,{to:"#_7、结论"},{default:m(()=>a[18]||(a[18]=[n("7、结论")])),_:1,__:[18]})])])]),a[21]||(a[21]=r('<h2 id="摘要" tabindex="-1"><a class="header-anchor" href="#摘要"><span>摘要</span></a></h2><ul><li><p>基于相似度的向量检索促进了搜索和推荐等许多重要应用的发展，但由于大规模数据集和密集的数据读取，受限于单机的内存容量和带宽。在本文中，我们提出了 CoTra，一个用于分布式执行的可扩展向量检索系统。我们观察到<strong>计算效率</strong>与<strong>通信效率</strong>之间存在张力（tension），这也是实现良好扩展性的主要挑战：即在每台机器上独立处理本地向量会导致计算量激增，因为未能充分利用向量索引的剪枝能力；而在所有机器上运行<strong>全局索引</strong>（global index）则会引入丰富的数据依赖性，从而导致大量的通信。为了解决这种张力，我们利用了向量检索本质上是近似的且对<strong>异步执行</strong>具有鲁棒性这一事实。具体而言，我们在机器之间运行协同向量检索，并采用了算法与系统的协同设计，包括基于聚类的数据分区以减少通信、异步执行以避免通信停顿、以及任务推送（task push）以减少网络流量。为了使协同搜索更加高效，我们引入了一套系统优化措施，包括任务调度、通信批处理和存储格式优化。我们在真实数据集上评估了 CoTra，并与四个基线进行了比较。结果显示，当使用 16 台机器时，CoTra 的查询吞吐量相对于单机扩展了 9.8-13.4 倍，并且在 recall@10 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.95 时是表现最好的基线的 2.12-3.58 倍。</p></li><li><p><strong>关键词</strong>：向量检索，分布式系统，RDMA</p></li></ul><h2 id="_1、引言" tabindex="-1"><a class="header-anchor" href="#_1、引言"><span>1、引言</span></a></h2><ul><li><p>高维向量检索是许多现代应用的基础，因为它实现了从文本、图像到基因组序列等各种数据类型的语义相似度比较。具体来说，复杂的数据对象被映射为向量嵌入 [5, 8, 40, 64]，然后进行基于相似度的<strong>向量检索</strong>以检索与查询向量 [32] 最相似的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 个向量（例如，通过欧几里得距离度量）。由于精确向量检索需要对向量数据集中的高维向量进行线性扫描，<strong>近似向量检索</strong>（Approximate vector search）已被广泛采用，通过检索 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 个相似向量中的大部分（而非全部）来换取效率。近似向量检索为众多关键任务提供支持，如基于内容的搜索（例如图像和视频）[21, 25, 60]、推荐系统（例如电子商务产品和在线广告）[7, 18, 35, 51] 以及生物信息学 [4, 29, 44]。图 1 展示了一个流行的应用：大语言模型（LLM）的检索增强生成（RAG）[63]，其中文本块被嵌入为向量，用户提示作为查询，检索到的文本块为 LLM 生成响应提供外部知识。</p></li><li><p><img src="'+h+'" alt="image1" loading="lazy"></p></li><li><p>向量检索的最先进（state-of-the-art）索引是近邻图（proximity graph）[32, 54]。虽然有许多变体 [15, 33, 37]，其核心思想是将向量组织成一个图，其中每个向量是一个节点并连接到其相似的向量。向量检索通过<strong>图遍历</strong>（graph traversal）进行处理，该过程从一个固定的或随机的入口节点开始，在访问一个节点时计算其所有邻居的相似度，并维护一个<strong>候选队列</strong>（candidate queue）来记录已计算的相似度，并选择最相似但未访问的节点作为下一个访问节点。对于具有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span> 个向量的数据集，图遍历所需的相似度计算次数在规模上为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>log</mi><mo>⁡</mo><mi>N</mi></mrow><annotation encoding="application/x-tex">\\log N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span> [15, 33, 39]。</p></li><li><p><strong>动机与挑战。</strong> 可扩展的向量检索需要跨机器的分布式执行，以解决单机的内存容量和带宽限制，特别是当十亿级数据集和高维向量（数百维）在今天变得司空见惯时。更为关键的是，向量检索通常是<strong>内存受限</strong>（memory bound）的，因为现代 CPU 的速度超过了内存带宽，且每个查询访问大量的向量 [9]。如图 2 所示，在单机上将线程数从 8 扩展到 128，查询吞吐量（QPS）仅提高了 3-4 倍，远低于理想的 16 倍。这是因为内存带宽（我们的机器为 204 GB/s）已经饱和，因此超过某个点（在我们的实验中为 48）增加线程数将不会提高 QPS。出于同样的原因，基于磁盘的系统 [7, 48]（将向量保存在 SSD 上）也受到磁盘带宽的限制。相比之下，分布式解决方案可以利用多台服务器的聚合内存带宽来获得更高的吞吐量。</p></li><li><p><img src="'+g+'" alt="image2" loading="lazy"></p></li><li><p>然而，分布式向量检索面临着<strong>计算效率</strong>与<strong>通信效率</strong>之间的关键张力。最简单的解决方案是独立分片（称为 <strong>Shard</strong>），如图 1 中间所示。Shard 将向量分配到各台机器上，每台机器在其向量上构建本地索引。查询首先广播到所有机器进行本地处理，然后合并本地搜索结果以获得全局 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 个最相似的向量。虽然简单且被 Milvus [52] 和 Weaviate [12] 等流行的向量数据库所采用，但 Shard 的表现不佳：图 2 显示在 16 台机器上仅有 4-6 倍的 QPS 增益。这是因为近邻图的查询复杂度相对于数据集大小是次线性的（即 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>log</mi><mo>⁡</mo><mi>N</mi></mrow><annotation encoding="application/x-tex">\\log N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span>），因此将大型数据集划分为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 个（即机器数量）独立的子数据集意味着与在单个索引中组织所有向量相比，处理每个查询需要更多的相似度计算（即 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mi>log</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>N</mi><mi mathvariant="normal">/</mi><mi>M</mi><mo stretchy="false">)</mo><mo>&gt;</mo><mi>log</mi><mo>⁡</mo><mi>N</mi></mrow><annotation encoding="application/x-tex">M \\log(N/M) &gt; \\log N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.01389em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span>，其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi><mo>≫</mo><mi>M</mi></mrow><annotation encoding="application/x-tex">N \\gg M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≫</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span>）。</p></li><li><p>为了充分利用向量索引的剪枝能力并提高计算效率，一个自然的解决方案是在整个数据集上利用全局索引。如图 1 最右侧图所示，<strong>Global</strong> 在每台机器上保留部分向量及其邻接表，但一台机器上的向量可能连接到其他机器上的向量。每个查询被分配给一台机器进行处理，当图遍历访问一个节点时，其部分邻居可能驻留在远程机器上。在这种情况下，需要网络通信来获取这些邻居向量进行计算。然而，如图 2 所示，Global 的 QPS 也远低于理想的线性扩展。这是因为 Global 通过网络传输许多向量，这些向量尺寸较大，很容易使网络带宽饱和。此外，尽管单边远程直接内存访问（RDMA）通信的延迟（2-3 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span>）比 TCP/IP 短得多 [14, 26]，但它仍然是本地内存访问的 10 倍以上。此外，由于一个查询需要许多通信操作，且只有在用远程向量更新候选队列后才能确定下一个访问节点，我们观察到 Global 的查询延迟是单机的 10-20 倍。</p></li><li><p><strong>我们的解决方案：CoTra。</strong> 我们提出了 CoTra，一个分布式向量检索系统，解决了计算效率与通信效率之间的张力。如图 2 所示，CoTra 的 QPS 显著高于 Shard 和 Global，并且超过了理想线性扩展的 0.8 倍。据我们所知，CoTra 是第一个在多台机器上运行整体近邻图索引（holistic proximity graph index）并实现相对于单机近邻图接近线性扩展的系统。</p></li><li><p>为了避免 Global 的网络饱和，我们从<strong>计算推送</strong>（computation-push）开始，即将计算距离的任务推送到远程机器，而不是拉取大型向量。虽然计算推送有效地减少了网络流量，但其 QPS 仍然很低。这是因为远程距离计算任务具有不稳定的延迟，这降低了对近邻图遍历至关重要的候选队列的质量。特别是，如果一个节点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi></mrow><annotation encoding="application/x-tex">u</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span></span></span></span> 的距离小于当前的最佳候选 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 但返回较晚，图遍历将访问 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span>，这是次优的，从而浪费了计算。图 3 说明了这一点，我们在访问一些节点后延迟更新候选队列，随着中等延迟（例如 16）的增加，计算量急剧上升。我们也尝试了几种数据分区技术，但发现很难将每个查询所需的向量集中到单台机器上以避免通信。</p></li><li><p><img src="'+d+'" alt="image3" loading="lazy"></p></li><li><p>计算推送的失败表明，在减少通信时应保持候选质量，CoTra 通过算法-系统协同设计实现了这一目标。具体而言，利用 K-means 以基于相似度的方式将向量划分到机器上。对于每个查询，这允许将机器区分为拥有许多被访问向量的<strong>主节点</strong>（primaries）和拥有少量被访问向量的<strong>次节点</strong>（secondaries）。此外，主节点机器上的向量通常离查询更近。因此，我们对主节点和次节点机器使用不同的执行策略。主节点机器运行 <strong>Co-Search</strong>，工作方式类似单机搜索，但其本地候选队列会定期同步，以确保候选的质量。次节点机器运行 <strong>Push-Pull</strong>，按需发送向量或为主节点机器计算距离；它们可能会有较长的延迟来更新候选队列，但由于其向量通常离查询较远，因此性能下降有限。</p></li><li><p>CoTra 还结合了一套系统优化措施来提高效率。首先，作为基本操作，Co-Search 和 Push-Pull 都在 RDMA 上高效实现。其次，在每台机器上进行任务调度，以重叠计算和通信，并避免候选队列的长同步延迟。第三，仔细批处理同一台机器上的通信任务，以减少所需的 IO 操作。最后，我们定制了近邻图索引的分布式存储格式，以实现高效的通信和任务执行。我们还实现了一个分布式过程，用于为无法放入单台机器的大型向量数据集构建全局近邻图索引。</p></li><li><p>我们在多达 10 亿个向量的四个大规模向量数据集上评估了 CoTra，将其与 Shard、Global 和一个最先进的分布式向量数据库进行比较。结果表明，CoTra 始终比所有基线实现更高的 QPS，并且在增加机器数量时具有接近线性的 QPS 扩展。我们的分析和消融研究也验证了我们设计的有效性。</p></li><li><p>综上所述，我们做出了以下主要贡献：</p><ul><li>我们通过扩展内存容量和带宽来激励分布式向量检索。我们还通过分析确定了良好扩展性的关键挑战是计算效率与通信效率之间的张力。</li><li>我们提出了一种协同搜索机制，实现了机器间细粒度的向量检索协调，在低通信成本下保持了计算效率。</li><li>我们为 CoTra 定制了一套系统优化措施，包括任务调度、通信批处理、索引存储和分布式索引构建。</li><li>我们开源了 CoTra 并对其性能进行了广泛评估，为设计选择提供了见解。</li></ul></li></ul><h2 id="_2、背景" tabindex="-1"><a class="header-anchor" href="#_2、背景"><span>2、背景</span></a></h2><ul><li>在这一部分，我们介绍了向量检索和 RDMA 的基础知识，以便于后续讨论。</li></ul><h3 id="_2-1-向量检索与近邻图索引" tabindex="-1"><a class="header-anchor" href="#_2-1-向量检索与近邻图索引"><span>2.1 向量检索与近邻图索引</span></a></h3><ul><li><p>向量检索也称为最近邻搜索（NNS），定义如下。</p></li><li><p><strong>定义 2.1。</strong> 给定一个大小为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span> 的向量数据集 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mo stretchy="false">{</mo><msub><mi>x</mi><mn>1</mn></msub><mo separator="true">,</mo><msub><mi>x</mi><mn>2</mn></msub><mo separator="true">,</mo><mo>⋯</mo><mtext> </mtext><mo separator="true">,</mo><msub><mi>x</mi><mi>N</mi></msub><mo stretchy="false">}</mo><mo>⊂</mo><msup><mi mathvariant="double-struck">R</mi><mi>d</mi></msup></mrow><annotation encoding="application/x-tex">X = \\{x_1, x_2, \\cdots, x_N\\} \\subset \\mathbb{R}^d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">X</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">⋯</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.10903em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⊂</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span>，一个查询向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi><mo>∈</mo><msup><mi mathvariant="double-struck">R</mi><mi>d</mi></msup></mrow><annotation encoding="application/x-tex">q \\in \\mathbb{R}^d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span>，以及所需向量的数量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span>，返回一个向量集合 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi><mo>⊂</mo><mi>X</mi></mrow><annotation encoding="application/x-tex">S \\subset X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⊂</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">X</span></span></span></span>，满足 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∥</mi><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><mi>q</mi><mi mathvariant="normal">∥</mi><mo>≤</mo><mi mathvariant="normal">∥</mi><msub><mi>x</mi><mi>j</mi></msub><mo>−</mo><mi>q</mi><mi mathvariant="normal">∥</mi><mo separator="true">,</mo><mi mathvariant="normal">∀</mi><msub><mi>x</mi><mi>i</mi></msub><mo>∈</mo><mi>S</mi><mo separator="true">,</mo><msub><mi>x</mi><mi>j</mi></msub><mo>∈</mo><mi>X</mi><mo>−</mo><mi>S</mi></mrow><annotation encoding="application/x-tex">\\|x_i - q\\| \\le \\|x_j - q\\|, \\forall x_i \\in S, x_j \\in X - S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mord">∥</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mord">∥</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∀</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.05724em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.07847em;">X</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span></span></span></span> 且 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∣</mi><mi>S</mi><mi mathvariant="normal">∣</mi><mo>=</mo><mi>k</mi></mrow><annotation encoding="application/x-tex">|S| = k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span>。</p></li><li><p>除了欧几里得距离，相似度函数也可以是内积或余弦相似度。由于嵌入向量通常具有高维度（例如 100 甚至 &gt;1000），精确 NNS 需要线性扫描。因此，近似 NNS（ANNS）在实践中经常被采用，它返回 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 邻居中的大部分而不是全部，以换取效率。ANNS 的结果质量由<strong>召回率</strong>（recall）衡量，定义为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∣</mi><mi>S</mi><mo>∩</mo><msup><mi>S</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mi mathvariant="normal">∣</mi><mi mathvariant="normal">/</mi><mi>k</mi></mrow><annotation encoding="application/x-tex">|S \\cap S&#39;|/k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∩</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mord">∣/</span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span>，其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>S</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup></mrow><annotation encoding="application/x-tex">S&#39;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 是包含 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 个向量的近似结果集。应用通常需要高召回率（例如 0.9 或 0.95）。ANNS 需要处理大型向量数据集（例如，对于具有数万亿 token 的 RAG [45]）并提供高查询处理吞吐量（QPS）（例如，用于搜索和推荐 [7, 10]）。为了面向用户的应用的服务质量（QoS），还需要短的查询延迟（例如 10-100ms）。</p></li><li><p>近邻图 [19] 是向量检索的最先进索引 [19]，与其他索引（如 IVF 和 LSH）相比，达到相同召回率所需的距离计算要少得多。其核心思想是将每个向量与其相似的向量连接起来形成一个图，如图 4 所示。向量检索通过算法 1 中的图遍历过程进行。<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 是一个最小优先队列，称为<strong>候选队列</strong>。算法 1 的第 3 行用入口节点（即 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>v</mi><mn>0</mn></msub></mrow><annotation encoding="application/x-tex">v_0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）初始化 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>；第 4-9 行通过计算 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 的邻居的距离来检查 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中最相似但未访问的节点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span>。注意，已访问的节点仍然可以驻留在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中（即，第 5 行使用 read 而不是 pop，并且 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 通过丢弃距离大的向量来满足大小限制 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span>。用户配置 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 来控制搜索结果的质量，较大的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 会产生较高的召回率，但代价是处理时间更长。近邻图具有良好的性能，因为（i）图识别出好的候选者，即如果一个向量与查询相似，它的邻居也可能相似；（ii）通过每次访问最相似的向量，图遍历逐渐移动到向量检索的结果，如图 4 所示。</p></li><li><p><img src="'+u+'" alt="image4" loading="lazy"></p></li><li><p><img src="'+x+'" alt="algo1" loading="lazy"></p></li></ul><h3 id="_2-2-远程直接内存访问" tabindex="-1"><a class="header-anchor" href="#_2-2-远程直接内存访问"><span>2.2 远程直接内存访问</span></a></h3><ul><li><p>远程直接内存访问（RDMA）是一种用于服务器之间高吞吐量、低延迟通信的网络技术。与 TCP/IP 网络不同（后者因内核处理和数据复制而产生显著开销），RDMA 允许绕过远程操作系统，直接读取或写入远程内存。现代 RDMA 网络实现了 40-400 Gbps 的带宽 [27, 57]，远超过以太网的 10-25 Gbps，端到端延迟在微秒级（即 us）。RDMA 已被广泛用于设计高效的分布式系统，如数据库 [65] 和机器学习 [22]。</p></li><li><p>RDMA 操作被抽象为 <strong>verbs</strong>，这是一组低级原语，包括<strong>单边 verbs</strong>和<strong>双边 verbs</strong>。单边 verbs（例如 READ, WRITE 和原子操作如 compare-and-swap/CAS）在没有远程 CPU 参与的情况下执行，因此非常适合延迟敏感型任务。双边 verbs（例如 SEND/RECV）类似于 TCP/IP 语义，即需要发送方和接收方 CPU 之间的协调，通常用于控制消息或兼容性。</p></li><li><p>使用 RDMA 进行向量检索的关键挑战是平衡通信延迟和带宽利用率。特别是，单边 RDMA verbs 具有低延迟（例如，在我们的集群中，当有效载荷低于 2KB 时为 2-3 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>μ</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">\\mu s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mord mathnormal">s</span></span></span></span>），但只能访问连续的远程内存进行读/写操作。然而，向量检索遵循近邻图对向量进行细粒度的随机访问。此外，由于网卡（NIC）的物理限制 [46]，RDMA 通信的吞吐量受到网络带宽和每秒 I/O 操作数（IOPS）的限制。例如，为了充分利用我们集群中的 56 Gbps 带宽，由于 IOPS 有限，有效载荷必须超过 1KB。然而，单个向量可能小于 1KB，例如，一个 128 维的浮点向量仅占 128B。</p></li></ul><h2 id="_3、分布式协同遍历" tabindex="-1"><a class="header-anchor" href="#_3、分布式协同遍历"><span>3、分布式协同遍历</span></a></h2><ul><li><p>我们构建 CoTra 作为一个系统，通过基于 RDMA 有效地扩展内存能力和带宽，释放多台机器上分布式向量检索的潜力。它旨在以良好的扩展性在分区的全局图上运行分布式搜索，即查询处理吞吐量（QPS）应随机器数量线性增加。为此，我们设计了一种协同图遍历过程，以便在多台机器上高效地为每个查询运行近邻图搜索算法（即算法 1）。</p></li><li><p><strong>数据布局。</strong> 为了充分利用向量索引的剪枝能力，CoTra 在整个数据集上采用整体近邻图，我们将在第 4 节讨论如何构建该图。如图 1(c) 所示，每台机器在图索引中保存相似数量的向量及其邻接表。由于图是整体的，一台机器上的向量可能连接到其他机器上的向量。具体而言，我们使用平衡 K-means 对向量数据集进行分区，并将每个分区分配给一台机器。这旨在使一台机器上的向量彼此相似，并将每个查询访问的向量集中到少数几台机器上以获得良好的局部性。</p></li></ul><h3 id="_3-1-观察与设计见解" tabindex="-1"><a class="header-anchor" href="#_3-1-观察与设计见解"><span>3.1 观察与设计见解</span></a></h3><ul><li><p>在介绍我们的协同遍历之前，我们先提出激发其设计的见解。</p></li><li><p><strong>数据局部性。</strong> 我们首先检查 K-means 分区在改善访问局部性方面的有效性。如果每个查询主要访问一台机器上的向量，并且我们将查询分配给这台机器进行处理，那么通信量将很小。图 5 显示情况并非如此，即虽然 Query 2 主要访问 Partition 8 上的向量，但 Query 1 访问的向量更均匀地分散在各个分区上。通过对许多查询取平均值，我们发现 73.8% 的被访问向量驻留在最热的分区上，并注意对于不同的查询，最热的分区是不同的。因此，如果我们把每个查询分配给其最热的分区进行处理，大约 25% 的向量访问需要通过网络进行。由于内存和网络之间巨大的带宽差异，这仍将使网络成为瓶颈。例如，我们的机器具有 204 GBps 的内存带宽和 56 Gbps 的网络带宽；为了跟上本地内存处理并通过网络读取 25% 的向量，所需的带宽应为 350 Gbps。因此，除了 K-means 分区外，还需要其他设计来降低通信成本。</p></li><li><p><img src="'+w+'" alt="image5" loading="lazy"></p></li><li><p>我们也尝试了更复杂的数据分区。即首先构建近邻图，然后使用最小割（min-cut）将其节点划分到机器上，使跨分区边的数量最小化。然而，访问局部性仅比 K-means 略有改善。这是因为一些查询不可避免地驻留在分区的边界上。因此，由于 K-means 的简单性，我们选择了它。</p></li><li><p>在图 5 中，对于每个查询，我们可以清楚地区分具有许多访问的热门分区（例如，Query 1 的 Partition 2, 4, 5, 7，Query 2 的 Partition 8）和具有少量访问的冷门分区（例如，Query 1 的 Partition 1, 3, 6, 8）。我们将热门分区称为<strong>主分区</strong>（primary partitions），冷门分区称为<strong>次分区</strong>（secondary partitions）。</p></li><li><p><strong>见解 1。</strong> <em>K-means 分区改善了数据局部性，并允许为每个查询区分主分区和次分区。然而，通信仍然是瓶颈。</em></p></li><li><p><strong>候选质量。</strong> 由于向量检索本质上是近似的，我们并不真的需要忠实地执行算法 1。为了降低通信成本，我们可以灵活控制通信的数量和频率。然而，这些通信设计应限制其对计算效率的影响，即每个查询为达到目标召回率所需的距离计算次数。特别是，我们发现算法 1 的计算效率由候选队列 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 决定。也就是说，我们可能会跳过或延迟远程机器上向量的一些距离计算；如果这些计算涉及一个节点（即向量）<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi></mrow><annotation encoding="application/x-tex">u</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span></span></span></span>，它比 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中当前最好的未访问节点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 更好，即 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">∥</mi><mi>q</mi><mo>−</mo><mi>u</mi><mi mathvariant="normal">∥</mi><mo>&lt;</mo><mi mathvariant="normal">∥</mi><mi>q</mi><mo>−</mo><mi>v</mi><mi mathvariant="normal">∥</mi></mrow><annotation encoding="application/x-tex">\\|q - u\\| &lt; \\|q - v\\|</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">u</span><span class="mord">∥</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="mord">∥</span></span></span></span>，访问 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 可能会导致图遍历走弯路并浪费计算。图 3 也显示，如果候选质量因更新延迟而下降，计算量会增加。相反，如果候选队列可以产生与单机执行相同的节点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 进行访问，计算效率将不会受到影响。</p></li><li><p>上述分析表明，为了避免降低候选队列的质量，我们的通信设计应优先考虑高质量向量（即距离查询较近的向量）并歧视低质量向量（即距离较大的向量）。图 5 显示，主分区和次分区对候选质量有信息价值，因为来自主分区的向量（例如，Query 1 的 Partitions 2, 4, 5, 7）通常比来自次分区的向量（例如，Query 1 的 Partitions 1, 3, 6, 8）距离查询更近。</p></li><li><p><strong>见解 2。</strong> <em>距离查询较近的向量应优先考虑以保持候选队列的质量。来自主分区的向量通常离查询更近。</em></p></li></ul><h3 id="_3-2-协同图遍历概述" tabindex="-1"><a class="header-anchor" href="#_3-2-协同图遍历概述"><span>3.2 协同图遍历概述</span></a></h3><ul><li><p>我们在第 3.1 节的观察表明，对于每个查询，在近距离拥有许多被访问向量的主分区和在远距离拥有少量被访问向量的次分区应区别对待。因此，如图 6 所示，我们首先使用<strong>导航索引</strong>（navigation index）来有效区分主分区和次分区。然后，我们使用不同的模式来协调机器（即分区）进行协同图遍历。具体而言，主分区在 <strong>Co-Search</strong> 模式下工作，通过维护自己的候选队列，在本地向量上运行距离计算，并向其他分区（即主分区和次分区）发送距离计算请求。主分区的本地候选队列定期同步，以确保<strong>有界延迟</strong>（bounded delay）和候选的质量。相比之下，次分区在 <strong>Pull-Push</strong> 模式下工作，按主分区的请求发送向量或计算距离，而不维护本地候选队列。</p></li><li><p><img src="'+y+'" alt="image6" loading="lazy"></p></li><li><p><strong>我们在低通信成本下保持候选质量的设计核心思想。</strong> 首先，主分区不交换向量和距离，因为许多向量在它们上面被访问；相反，本地候选队列要小得多，适合交换。其次，为了确保候选质量，主分区进行同步以保证有界延迟，因为它们的向量通常离查询较近；次分区上的任务具有较宽松的同步要求，因为它们的向量通常离查询较远。第三，次分区不维护候选队列，因为只有少量向量在它们上面被访问，因此交换向量和距离的通信成本是适中的。</p></li><li><p><strong>导航索引（Navigation Index）。</strong> 我们从数据集中采样一小部分（例如 1%）向量，并在这些向量上构建近邻图索引作为导航索引。导航索引在所有机器上复制，每个查询首先被分配给一台随机机器进行初始化。该机器使用导航索引搜索查询，以确定其主分区和次分区。具体而言，我们在导航索引中找到查询的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 邻居，并计算这些邻居中有多少驻留在每个分区（整个数据集的）上。如果一个分区包含超过 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mi mathvariant="normal">/</mi><mi>M</mi></mrow><annotation encoding="application/x-tex">k/M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 个这些邻居（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 是分区数量），则该分区为主分区，否则为次分区。</p></li><li><p>为了加速查询处理，我们使用来自导航索引的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 邻居来初始化主分区的本地候选队列。每个主分区收集驻留在其上的邻居，而次分区上的邻居被发送到拥有这些 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 邻居数量最多的主分区。</p></li><li><p><strong>协同遍历搜索。</strong> 算法 2 详细介绍了我们协同遍历的查询处理过程。</p></li><li><p><img src="'+k+'" alt="algo2" loading="lazy"></p></li><li><p>在第 3-4 行中，搜索导航索引以识别主机器和次机器，并将子查询（即候选队列）分发到主机器（图 6 ①<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">→</span></span></span></span>②），这些机器在第 5-12 行开始图遍历。本地遍历遵循算法 1，即每次迭代从候选队列中提取最有希望的候选者，遍历其邻居，并根据其目标向量所在的机器将计算任务打包成不同的消息类型，如计算任务和同步消息。</p></li><li><p>每个子查询处理其本地任务，同时并发更新同步消息（第 13 行）。基于从查询消息队列接收到的消息（包含来自其他主机器的远程计算结果和同步数据），子查询更新其候选队列（第 14-15 行）。终止检测算法（第 16 行，将在 4.3 节详细介绍）在候选队列为空时激活。</p></li></ul><h3 id="_3-3-执行模式详情" tabindex="-1"><a class="header-anchor" href="#_3-3-执行模式详情"><span>3.3 执行模式详情</span></a></h3><ul><li><p>我们在 RDMA 上高效地实现了用于协同遍历的 Pull-Push 和 Co-Search 模式。图 7 提供了一个说明，详细介绍如下。</p></li><li><p><strong>Pull-Push 模式。</strong> 我们使用它从次机器拉取向量并将距离计算任务推送到次机器。</p></li><li><p><img src="'+M+'" alt="image7" loading="lazy"></p><ul><li><strong>Pull-Data</strong>：如图 7(a) 所示，当访问一个候选者时，其部分邻居可能驻留在远程机器上。CoTra 可以根据其 ID 确定这些目标向量的远程内存地址，并通过 RDMA 单边原语检索它们。预分配的本地缓冲区用于存储检索到的向量，并采用异步单边 READ 原语以避免通信停顿。</li><li><strong>Task-Push</strong>：为了减少传输大型向量的带宽消耗，CoTra 可以使用如图 7(b) 所示的任务推送。具体来说，待计算向量的 ID 使用单边 RDMA 写入被写入远程机器的任务队列。远程机器从队列中检索任务，对指定向量执行计算，并仅将距离返回给请求机器。注意，每个查询只需发送到机器一次。</li></ul></li><li><p>当远程机器拥有的邻居数少于或等于当前访问节点的两个邻居时，我们使用 <em>Pull-Data</em>，否则使用 <em>Task-Push</em>。这是因为 <em>Pull-Data</em> 不涉及远程机器的 CPU，因此具有更短的延迟。这很有利，但在有许多远程邻居时可能会产生过多的带宽消耗。经验上，我们观察到将阈值设置为 2 可以平衡延迟和带宽。</p></li><li><p><strong>Co-Search 模式。</strong> 主机器使用 Co-Search 模式交换查询状态，如图 7(c) 所示。具体而言，交换的消息包括：</p><ul><li>自上次同步以来插入候选队列的新候选者。</li><li>节点被添加到候选队列的当前距离上界。一个节点必须具有比该界限更小的距离才能进入候选队列。</li><li>自上次同步以来需要在远程机器上计算距离的向量。</li></ul></li><li><p>这些消息按目标机器分组并打包发送。Co-Search 在访问固定数量的候选者（默认为 4）后进行同步，以确保候选者的质量。使用同步消息，每个主机器更新其本地候选队列和距离上界（取所有界限的最小值），并检查本地要遍历的候选者是否已被其他机器访问。如果没有，它将遍历候选者以更新本地候选队列，如算法 1 所示。距离上界用于拒绝不能添加到候选队列的候选者。</p></li></ul><h2 id="_4、优化与实现" tabindex="-1"><a class="header-anchor" href="#_4、优化与实现"><span>4、优化与实现</span></a></h2><h3 id="_4-1-rdma-友好的图布局" tabindex="-1"><a class="header-anchor" href="#_4-1-rdma-友好的图布局"><span>4.1 RDMA 友好的图布局</span></a></h3><ul><li><p>为了降低通信成本，我们为向量检索和 RDMA 定制了一种图存储格式。具体来说，我们以解耦的方式存储近邻图索引，其中节点在远程机器上的邻居存储在远程机器上。如图 8 所示，每个节点的邻接表由本地边和指向远程边的指针组成。为了配合混合 <em>Pull-Push</em> 模式，每个节点存储指向高出度远程邻居数组的指针和低出度远程邻居的 ID。使用这种存储格式，<em>Pull-Push</em> 模式可以进一步减少网络带宽，因为大边的传输被指针所取代。</p></li><li><p><img src="'+b+'" alt="image8" loading="lazy"></p></li><li><p>为了进行高效的内存访问，我们实现了细粒度的预取。近邻图上的向量检索进行许多随机内存访问，包括本地向量读取、图邻接表遍历和访问列表操作。我们主动发出预取指令以重叠数据传输与计算。在构建图索引时，我们按各自的远程机器对每个节点的邻居进行预分组，并将元数据分配给驻留在同一台机器上的邻居。元数据包括远程分区的 ID 和该远程分区中的邻居数量。此外，我们采用固定大小的邻居数组进行内联存储分配，允许从节点 ID 直接计算偏移量。这通过可预测的内存寻址消除了初始数组访问的缓存未命中。</p></li></ul><h3 id="_4-2-高-cpu-利用率的任务调度" tabindex="-1"><a class="header-anchor" href="#_4-2-高-cpu-利用率的任务调度"><span>4.2 高 CPU 利用率的任务调度</span></a></h3><ul><li><p>为了提高吞吐量并流水线化计算和通信，CoTra 同时处理多个查询。然而，这可能导致查询延迟增加，因为某些查询可能会因缺乏计算而被饿死。为了平衡查询延迟和吞吐量，CoTra 使用 C++ 协程将每个查询分解为细粒度的操作符，每个操作符代表一跳。通过调度这些操作符，CoTra 避免了饿死并实现了查询间的负载均衡。</p></li><li><p><strong>Query routine（查询例程）。</strong> CoTra 为每个查询创建一个查询例程，它是一个状态机。如图 9 所示，每个查询从开始到结束经历四个状态：</p><ul><li><em>Pre-Stage</em>：如 3.2 节所述，在此阶段，查询搜索导航索引以确定其主机器和次机器。子查询随后被分发到主机器。每台主机器创建一个查询例程并进入第二个状态。</li><li><em>Post-Stage</em>：在此阶段，查询执行本地搜索和遍历，计算候选节点的距离，更新候选队列，并与其他主机器同步消息。处理完当前候选队列中固定数量的节点后，它过渡到下一个状态。</li><li><em>Pause</em>：在此阶段，查询进入挂起状态并启动分布式终止算法。如果在此期间收到的新同步消息可以提供新的候选节点，查询将被重新激活并返回到 post-stage。否则，它使用终止检测算法等待终止令牌。</li><li><em>End</em>：当查询成功检测到终止时，其本地搜索结果被发送回原始机器，原始机器合并这些结果以获得最终的 top-<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 向量。</li></ul></li><li><p><img src="'+v+'" alt="image9" loading="lazy"></p></li><li><p>如图 9 所示，我们使用例程队列管理查询。每个线程重复执行两个过程，即处理远程任务和推进查询例程。当处理远程任务时，如 3.3 节所述，线程从任务队列中检索计算任务并返回结果。处理完任务队列后，线程从例程队列中弹出一个查询例程并执行一步。如果查询例程保持在 post-stage 状态，它将被重新插入例程队列以进行下一轮。如果它过渡到 Pause 或 End 状态，则不会重新插入例程队列。</p></li><li><p><strong>负载均衡。</strong> 由于查询的动态性质，每个线程处理的子查询数量可能会变得不均匀。为了实现负载均衡，我们采用多线程任务池来管理查询计算。查询例程创建的任务被放置在所有线程共享的队列中。处理完任务队列后，线程检查查询例程是否有子查询，并从共享队列执行任务窃取。</p></li></ul><h3 id="_4-3-实现细节" tabindex="-1"><a class="header-anchor" href="#_4-3-实现细节"><span>4.3 实现细节</span></a></h3><ul><li><p>我们用 27K 行 C++ 代码实现了 CoTra，包括分布式查询处理和索引构建。CoTra 可以部署在通用 RDMA 集群上，并支持不同的图索引。</p></li><li><p><strong>通信批处理和流水线。</strong> 为了有效地利用 RDMA，我们合并小消息（例如，向量到查询的距离）。通过减少消息数量，解决了 NIC 的 IOPS 瓶颈。为了支持高效的消息传递并避免过多的内存消耗，我们设计了一个基于环形缓冲队列的单边写入队列。当一台机器收到一定数量的单边写入操作时，它返回已释放缓冲区的 ID，允许远程消息缓冲区重新进入环形缓冲队列以供重用。</p></li><li><p><strong>分布式查询终止。</strong> 在 <em>Co-Search</em> 模式下，查询终止具有挑战性。由于查询处理的动态性质，子查询在本地终止后，收到来自远程机器的更新消息后仍可能被激活并继续执行。注意到 ANNS 和单源最短路径算法之间的相似性，我们基于 Dijkstra 风格的 2-pass 环形终止检测 [41] 实现了一个分布式终止检测算法。具体而言，在查询执行期间，每个子查询被分配一个标识符标志，并且在任何给定时间只有一个子查询持有终止令牌。当一个子查询完成其执行时，它将令牌传递给下一个子查询。接收令牌的子查询根据自上次持有令牌以来是否执行了新的计算以及其标志的状态来确定令牌的值。此过程由每个子查询重复进行，如果同一令牌在子查询之间循环两次，则可以安全地终止查询。</p></li><li><p><strong>分布式索引构建。</strong> 我们为超过单台机器内存的向量数据集构建近邻图索引，遵循 DiskANN [48] 的基于副本的分区方法。其思想是通过 K-means 对数据集进行分区，将每个向量发送到多个分区，并合并分区的本地索引，使得由于分区之间的复制节点，图是连通的。我们将整个过程分为三个阶段，即 <em>dispatch（分发）</em>、<em>build（构建）</em> 和 <em>merge（合并）</em>。在分发阶段，每台机器收集发往每台其他机器的向量（由数据集样本上的 K-means 确定）并批量发送到目标机器。每个向量被发送到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi></mrow><annotation encoding="application/x-tex">S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span></span></span></span> 个最近的机器（DiskANN 中默认 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">S=2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>）。每台机器独立在其分配的向量上构建本地近邻图。在合并阶段，机器执行分布式合并操作以去重节点并生成最终图。CoTra 默认使用 Vamana [48] 作为图索引，因为其性能良好。然而，CoTra 也可以使用其他近邻图索引（如 HNSW [33] 和 NSG [15]）进行构建和搜索。</p></li><li><p><strong>使用常规网络。</strong> 由于 CoTra 主要通信距离而不是原始向量，我们观察到其带宽消耗较低。因此，以太网相对于 RDMA 的主要缺点是通信延迟较长。这增加了同步延迟，从而降低了候选质量。结果是，每个查询可能需要更多的计算。我们将测试和调整 CoTra 以适应以太网留待未来工作。</p></li></ul><h2 id="_5、评估" tabindex="-1"><a class="header-anchor" href="#_5、评估"><span>5、评估</span></a></h2><ul><li>我们进行了广泛的实验，将 CoTra 与最先进的分布式向量检索系统进行比较，验证 CoTra 的可扩展性，并提供性能增益的系统分析以及消融研究。</li></ul><h3 id="_5-1-实验设置" tabindex="-1"><a class="header-anchor" href="#_5-1-实验设置"><span>5.1 实验设置</span></a></h3><ul><li><p><strong>数据集。</strong> 在我们的实验中，我们在四个主流基准数据集 [47, 49] 上评估我们的系统：SIFT [31]、DEEP [3]、Text-to-Image [13] 和 LAION [43]。为了全面评估不同规模的性能，我们在 SIFT 和 DEEP 数据集上分别使用 100M 和 1B 向量进行实验，而 100M 子集用于所有四个数据集的评估。Text2Image 中查询的数据分布与索引数据不同，我们在该数据集上验证了 CoTra 处理分布外数据的能力。我们通过利用来自 LAION 的图像嵌入来评估系统在高维向量数据集上的搜索性能。</p></li><li><p>这种实验设计能够系统地分析不同数据量和不同数据分布特征下的系统行为。我们在表 1 中总结了数据集配置。</p></li><li><p><img src="'+_+'" alt="table1" loading="lazy"></p></li><li><p><strong>基线。</strong> 我们将我们的系统与几个代表性的基线实现进行评估，包括最先进的单机和分布式系统，以及我们开发的两种 RDMA 优化方法。选定的基线包括：</p><ul><li><strong>DiskANN (Single)</strong> [48]：最先进的十亿级图解决方案，完全在内存中运行以获得最佳性能。我们包括纯内存实现以演示具有多个 CPU 和大内存的单机配置中的潜在内存瓶颈，突显分布式系统中可扩展性的重要性。</li><li><strong>Milvus</strong> [52]：采用固定大小分区图索引的最流行的分布式向量数据库，仅在 100M 数据集上评估，因为存储要求巨大（100M 向量大约需要 2TB，1B 向量需要 20TB）。固定大小的分片方法在处理大规模数据集时会导致过多的碎片化，从而需要搜索过程遍历大量分片并产生大量冗余计算。</li><li><strong>Global</strong>：基于 RDMA 的实现，使用单边 READ 操作进行向量数据访问，采用 K-means 分区和整体图索引。该方法针对通过 RDMA 直接访问远程内存进行了优化，消除了数据检索操作期间的服务器端处理需求。</li><li><strong>Shard</strong>：在 scatter-and-gather 模式下运行的完全独立索引解决方案，其中查询分散在各分区进行独立搜索，结果通过 RDMA 收集。此设计最大化了分布式环境中的并行性，同时保持完全的分区独立性。</li></ul></li><li><p>基线图索引类型为 Vamana [48]，而 Milvus 使用 HNSW [33]。对于索引构建，我们遵循官方指南和实用建议来设置参数。</p></li><li><p><strong>测试平台。</strong> 实验评估在两种设置下进行。① 主要测试平台包括一个 16 节点的 RDMA 集群，每个节点配备 Intel Xeon Silver 4110 处理器（16 核）和 128 GB 主内存，运行 Ubuntu 22.04.4 LTS。集群采用 56-Gbps Mellanox MT27500 ConnectX-3 IB RNIC 连接到 56-Gbps InfiniBand 交换机。② 另一台服务器是单台机器，配备四个 Intel Xeon Gold 6252N 处理器，总内存为 768GB，其中每个 NUMA 节点包含 24 个物理核心和 48 个逻辑线程。该服务器用于评估内存解决方案，该方案随单机线程数扩展。</p></li><li><p>我们使用设置 ② 作为可扩展性评估的参考点，因为在较小规模数据集上的初步测试证实其性能与设置 ① 中的单个节点相当。此验证确保可以在单机基线和分布式配置之间进行有意义的相对性能测量。所有实验结果均报告为五次运行的平均值，以确保统计可靠性。</p></li><li><p><strong>性能指标。</strong> 遵循先前的工作 [7, 15, 33, 47, 48]，我们使用达到目标召回率的每秒查询数（QPS）来衡量系统吞吐量，并采用 recall@k（k=10）作为默认精度指标，表示在真实 top-k 邻居中的搜索结果比率。我们在微观研究中设置 k=1 和 k=100 时也观察到了类似的性能趋势。</p></li></ul><h3 id="_5-2-搜索性能和可扩展性" tabindex="-1"><a class="header-anchor" href="#_5-2-搜索性能和可扩展性"><span>5.2 搜索性能和可扩展性</span></a></h3><ul><li><p><strong>在 1 亿规模数据集上的性能。</strong> CoTra 在 8 机和 16 机配置下均展示了卓越的可扩展性和搜索性能。如图 10 所示，CoTra 在 8 台机器上实现了比最佳基线（Shard）高 1.52–2.2 倍的改进，涵盖四个数据集（recall@10 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.95）。这种性能提升主要归功于图索引的完整性和细粒度执行模式（第 3.3 节）带来的增强的计算效率。</p></li><li><p><img src="'+S+'" alt="image10" loading="lazy"></p></li><li><p>图 11 展示了 16 台机器上四个 100M 数据集的 QPS-recall 曲线。与 8 机设置相比，吞吐量增益更为显著。具体而言，CoTra 在 512 维 LAION 数据集上表现良好，表现优于最佳基线 3.58 倍（recall@10 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.95），并在 Text2Image 数据集上保持稳健的性能，该数据集由于分布外效应表现出独特的 recall-QPS 特征，实现了 2.23 倍的提升（recall@10 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.95）。在 SIFT 和 DEEP 数据集上也观察到了 2.12–2.86 倍的提升。相比之下，Single 和 Global 索引配置未能随计算资源的增加而扩展。这是因为较大的向量尺寸加剧了单机系统中的内存带宽瓶颈，并增加了分布式环境中的通信开销。</p></li><li><p><img src="'+C+'" alt="image11" loading="lazy"></p></li><li><p>在所有数据集上，Shard 的基线实现始终优于 Milvus，并且 CoTra 在 8 机和 16 机配置下，在 recall@10 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.95 时实现了比 Milvus 高 8.7 倍到 33.3 倍的吞吐量提升。这是由于 Milvus 的固定分片分区策略与我们在 Shard 索引中的机器计数分片不同，导致更多的索引分片（在 Milvus 中称为 segments）。随着数据集大小的增加，引入了更多的分片，导致 Milvus 中的计算冗余更大，吞吐量更低。</p></li><li><p><strong>在 10 亿规模向量数据集上的性能。</strong> CoTra 在十亿级向量数据集上也提供了卓越的性能。图 12 展示了使用 16 台机器在 SIFT1B 和 DEEP1B 数据集上的查询吞吐量（QPS）与召回率的关系。在 100M 规模的 SIFT 和 DEEP 数据集上观察到的性能模式与 1B 规模相似，验证了系统的可扩展性。与 Shard 和 Global 方法相比，我们的系统实现了 2.2 - 2.8 倍的更高吞吐量（当 recall <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≥</mo></mrow><annotation encoding="application/x-tex">\\ge</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mrel">≥</span></span></span></span> 0.90。性能增益在所有召回率范围内都很明显，证明了 CoTra 对质量敏感型应用的有效性。</p></li><li><p><img src="'+P+'" alt="image12" loading="lazy"></p></li><li><p>在所有数据集和系统规模上观察到的一致加速进一步验证了 CoTra 的通用性。</p></li><li><p><strong>改变 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 的影响。</strong> 为了验证 CoTra 能够在 recall@k 中处理不同的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 值，我们在 Text2Image 数据集上进行了实验，这代表了一个具有挑战性的搜索场景。图 13 显示了 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>=</mo><mn>1</mn><mo separator="true">,</mo><mn>10</mn><mo separator="true">,</mo><mn>100</mn></mrow><annotation encoding="application/x-tex">k=1, 10, 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">10</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">100</span></span></span></span> 时的吞吐量性能，其中 CoTra 优于最佳基线 2.51–2.58 倍。尽管由于空间限制未在文中展示，但在其他数据集上也观察到了类似的模式。这些结果证实了 CoTra 在不同检索要求下的一致性能优势。</p></li><li><p><img src="'+T+'" alt="table2" loading="lazy"></p></li><li><p><img src="'+L+'" alt="image13" loading="lazy"></p></li><li><p><strong>可扩展性。</strong> 为了展示 CoTra 的可扩展性，我们在表 3 中展示了性能增益，其中报告的 QPS 改进是相对于具有 8 个线程的内存中 Single 基线的。CoTra 实现了出色的可扩展性，在 8 台机器上实现了 6.2-7.6 倍的改进，在 16 台机器上实现了 9.8-13.4 倍的 QPS 改进。</p></li><li><p><img src="'+f+'" alt="image14" loading="lazy"></p></li><li><p>CoTra 通过利用所提出的技术成功保持了近线性扩展。与 Shard 索引相比，CoTra 表现更优，并且每个查询所需的节点访问和计算显著更少，以达到相同的召回率水平。即使使用 RDMA，简单应用全局图索引（Global）也不能提供理想的性能，因为通信密集。CoTra 的这种效率源于全局图索引，它有效地保留了整个数据集的路由搜索路径，即使在分布式设置中也是如此，并增强了查询遍历，以及协同遍历的设计，它消除了分区方法（例如 Shard 和 Milvus）中看到的冗余计算并减少了通信。</p></li></ul><h3 id="_5-3-微观实验和消融研究" tabindex="-1"><a class="header-anchor" href="#_5-3-微观实验和消融研究"><span>5.3 微观实验和消融研究</span></a></h3><ul><li><p><strong>搜索成本分解。</strong> 为了理解 CoTra 的增益，我们评估了 SIFT100M 数据集上 16 台机器的不同基线的平均查询计算计数（计算效率）和通信时间在总执行时间中的比例（通信效率）。</p></li><li><p>如表 3 所示，单机系统表现出最低的平均计算计数和通信开销。然而，由于内存带宽限制，当线程数增加时，其吞吐量受到严重限制。Global 方法实现了第二高的计算效率，因为其搜索逻辑与单机系统非常相似。Shard 受到分区索引构建和搜索导致的计算操作增加的影响，导致超过 4 倍的冗余计算，从而限制了吞吐量。相比之下，CoTra 保持了相对较高的计算效率（仅引入约 20% 的冗余计算，这是由延迟更新引起的），同时实现了低通信开销（约 22% 的通信时间比例），最终提供了最高的吞吐量。</p></li><li><p><img src="'+D+'" alt="table3" loading="lazy"></p></li><li><p><strong>索引构建时间。</strong> CoTra 中的分布式并行图构建大大加快了与单机相比的索引构建速度。如表 4 所示，构建 DEEP1B 数据集的时间从 5 天多降至 16 个节点的仅 14 小时。单机设置在索引构建期间由于内存不足问题使用基于磁盘的索引 [48]（上述搜索评估是在内存中进行的）。</p></li><li><p><img src="'+N+'" alt="table4" loading="lazy"></p></li><li><p><strong>消融研究。</strong> 我们对本文提出的关键优化进行了全面评估，分析了它们对吞吐量和延迟改进的个人贡献。评估的组件包括：Pull-Push 模式（+PP），Co-Search 模式（+CS），图布局优化（+GL）和查询管理器（+QM）。</p></li><li><p>如图 15 所示。Pull-Push 模式消除了批量向量传输，带宽瓶颈得到显著缓解，导致吞吐量大幅提升。Co-Search 模式放宽了查询数据依赖性，消除了被动结果同步的需求。这允许小批量大小实现可比的 QPS，同时大幅提高整体吞吐量。优化的图布局结合我们的 Pull-Push 通信模式，进一步减少了通信开销。最后，查询管理器与其他系统优化相结合，通过细粒度的工作负载分区和平衡改进了计算调度，进一步提高了多线程场景下的延迟和吞吐量。</p></li><li><p><img src="'+A+'" alt="image15" loading="lazy"></p></li></ul><h2 id="_6、相关工作" tabindex="-1"><a class="header-anchor" href="#_6、相关工作"><span>6、相关工作</span></a></h2><ul><li><p><strong>内存向量检索系统。</strong> 向量索引研究主要考虑单机和内存设置 [2, 15, 24, 33]。两种类型的索引最受欢迎，即连接相似向量形成图的<strong>近邻图</strong> [33]，以及将向量划分为聚类的 <strong>IVF</strong> [24]。近邻图比 IVF 需要更少的距离计算就能达到相同的召回率 [33, 55]，因此我们的 CoTra 利用近邻图索引来享受其高效率。许多系统还针对内存查询处理进行了优化 [6, 34, 38]。例如，图重排序用于减少 [9] 中近邻图的随机向量访问引起的缓存未命中，而缓存未命中在 [1] 中通过软件预取解决。ParlayANN [34] 和 FAISS [23] 都为几种向量索引提供了高效的实现（例如 SIMD）。还有许多向量量化算法 [1, 16, 17, 24] 可以将每个向量压缩成更小的向量并加速距离计算。专注于分布式协调，我们的 CoTra 与这些单机引擎和向量量化研究正交，并可以整合它们以提高性能。</p></li><li><p><strong>混合向量检索系统。</strong> 几个系统使用磁盘存储大型向量数据集 [42, 50]。例如，DiskANN [48] 将压缩向量保留在内存中，而将精确向量和近邻图索引保留在磁盘上。Starling [53] 通过图重排序减少了 DiskANN 的磁盘读取放大。SPANN 使用 IVF 索引，将聚类中心保留在内存中，将向量保留在磁盘上 [7]。这些基于磁盘的系统具有成本效益，但吞吐量受到磁盘带宽的限制。一些系统使用 CPU-GPU 联合处理以从 GPU 的强大计算能力中受益 [36]。例如，Rummy 使用 IVF 索引并按需将聚类从 CPU 移动到 GPU 进行计算 [62]，而 Bang 使用近邻图索引并将邻接表从 CPU 移动到 GPU 以计算近似距离 [28]。对于这些系统，小 GPU 显存和 PCIe 带宽是主要的限制因素。</p></li><li><p><strong>分布式向量检索系统。</strong> 大多数系统通过在每台机器上构建独立索引来进行分布式向量检索，例如 Milvus [52]、AnalyticDB [56]、Weaviate [12]、Cassandra [30] 和 Pyramid [11]。这简化了系统设计，但降低了计算效率，如我们的分析所示。一些系统使用 IVF 索引进行分布式向量检索，例如 Auncel [61] 和 SPFresh [58]。好处是每台机器在确定排名靠前的聚类后只需扫描其本地聚类。然而，IVF 索引的计算效率低于近邻图。一些系统使用新硬件来扩展向量检索，例如 CXL-ANNS [20] 采用 Compute Express Link (CXL) 作为内存池，DF-GAS [59] 利用 FPGA 进行距离计算。据我们所知，CoTra 是第一个在整个数据集上使用整体近邻图索引进行分布式向量检索的系统。这享有高计算效率，但需要仔细的算法-系统协同设计来处理由近邻图索引的细粒度数据依赖性引起的大量通信。</p></li></ul><h2 id="_7、结论" tabindex="-1"><a class="header-anchor" href="#_7、结论"><span>7、结论</span></a></h2><ul><li>我们提出了 CoTra，一个在多台机器上扩展向量检索的系统。我们发现对整个数据集使用整体近邻图索引享有高计算效率，但受到丰富数据依赖性引起的广泛通信的影响。为了降低通信成本，我们通过观察如果候选质量好就可以保持近邻图搜索的效率来进行算法系统协同设计。我们还结合了系统优化，包括任务调度、RDMA 友好的图格式优化和分布式索引构建。据我们所知，CoTra 是第一个与单机近邻图相比实现接近线性吞吐量扩展的系统。</li></ul>',37))])}const E=p(z,[["render",Q]]),B=JSON.parse('{"path":"/article/reading/A-%E5%90%91%E9%87%8F%E6%95%B0%E6%8D%AE%E5%BA%93/N-CoTra/CoTra.html","title":"基于 RDMA 的高效可扩展分布式向量检索","lang":"zh-CN","frontmatter":{"title":"基于 RDMA 的高效可扩展分布式向量检索","date":"2025-07-09T00:00:00.000Z","category":"论文","tag":["Vector Search","Distributed Systems","RDMA","CoTra"],"feed":false,"seo":false,"head":[]},"headers":[{"level":2,"title":"摘要","slug":"摘要","link":"#摘要","children":[]},{"level":2,"title":"1、引言","slug":"_1、引言","link":"#_1、引言","children":[]},{"level":2,"title":"2、背景","slug":"_2、背景","link":"#_2、背景","children":[{"level":3,"title":"2.1 向量检索与近邻图索引","slug":"_2-1-向量检索与近邻图索引","link":"#_2-1-向量检索与近邻图索引","children":[]},{"level":3,"title":"2.2 远程直接内存访问","slug":"_2-2-远程直接内存访问","link":"#_2-2-远程直接内存访问","children":[]}]},{"level":2,"title":"3、分布式协同遍历","slug":"_3、分布式协同遍历","link":"#_3、分布式协同遍历","children":[{"level":3,"title":"3.1 观察与设计见解","slug":"_3-1-观察与设计见解","link":"#_3-1-观察与设计见解","children":[]},{"level":3,"title":"3.2 协同图遍历概述","slug":"_3-2-协同图遍历概述","link":"#_3-2-协同图遍历概述","children":[]},{"level":3,"title":"3.3 执行模式详情","slug":"_3-3-执行模式详情","link":"#_3-3-执行模式详情","children":[]}]},{"level":2,"title":"4、优化与实现","slug":"_4、优化与实现","link":"#_4、优化与实现","children":[{"level":3,"title":"4.1 RDMA 友好的图布局","slug":"_4-1-rdma-友好的图布局","link":"#_4-1-rdma-友好的图布局","children":[]},{"level":3,"title":"4.2 高 CPU 利用率的任务调度","slug":"_4-2-高-cpu-利用率的任务调度","link":"#_4-2-高-cpu-利用率的任务调度","children":[]},{"level":3,"title":"4.3 实现细节","slug":"_4-3-实现细节","link":"#_4-3-实现细节","children":[]}]},{"level":2,"title":"5、评估","slug":"_5、评估","link":"#_5、评估","children":[{"level":3,"title":"5.1 实验设置","slug":"_5-1-实验设置","link":"#_5-1-实验设置","children":[]},{"level":3,"title":"5.2 搜索性能和可扩展性","slug":"_5-2-搜索性能和可扩展性","link":"#_5-2-搜索性能和可扩展性","children":[]},{"level":3,"title":"5.3 微观实验和消融研究","slug":"_5-3-微观实验和消融研究","link":"#_5-3-微观实验和消融研究","children":[]}]},{"level":2,"title":"6、相关工作","slug":"_6、相关工作","link":"#_6、相关工作","children":[]},{"level":2,"title":"7、结论","slug":"_7、结论","link":"#_7、结论","children":[]}],"git":{"createdTime":1787540590000,"updatedTime":1787540590000,"contributors":[{"name":"z-ben","username":"z-ben","email":"12800262+z-ben@user.noreply.gitee.com","commits":1,"url":"https://github.com/z-ben"}]},"readingTime":{"minutes":43.18,"words":12955},"filePathRelative":"article/reading/A-向量数据库/N-CoTra/CoTra.md","localizedDate":"2025年7月9日"}');export{E as comp,B as data};
